import { formatTimestamp, convertToSeconds } from '../time';

describe('time utils', () => {
  describe('convertToSeconds', () => {
    test('should return time if no unit', () => {
      expect(convertToSeconds(1)).toEqual(1);
    });

    test('should return time if invalid unit', () => {
      expect(convertToSeconds(1, 'invalid')).toEqual(1);
    });

    test('should convert days to seconds', () => {
      expect(convertToSeconds(1, 'days')).toEqual(86400);
    });

    test('should convert hours to seconds', () => {
      expect(convertToSeconds(1, 'hours')).toEqual(3600);
    });

    test('should convert minutes to seconds', () => {
      expect(convertToSeconds(1, 'minutes')).toEqual(60);
    });
  });

  describe('formatTimestamp', () => {
    test('should default', () => {
      expect(formatTimestamp(0)).toEqual('');
      expect(formatTimestamp(1)).toEqual('Thu Jan 1, 1970 12:00 am UTC');
    });

    test('should convert to provided timezone', () => {
      expect(formatTimestamp(1, 'America/Denver')).toEqual(
        'Wed Dec 31, 1969 5:00 pm MST',
      );
    });

    test('should convert to privded format', () => {
      expect(formatTimestamp(1, 'UTC', 'DD MM YY h:mm A')).toEqual(
        '01 01 70 12:00 AM',
      );
    });
  });
});
